        py='def max_path_sum(root):\n    best = float("-inf")\n    def gain(n):\n        nonlocal best\n        if not n:\n            return 0\n        l = max(gain(n.left), 0)\n        r = max(gain(n.right), 0)\n        best = max(best, n.val + l + r)\n        return n.val + max(l, r)\n    gain(root)\n    return best',
        js='function maxPathSum(root) {\n  let best = -Infinity;\n  const gain = n => {\n    if (!n) return 0;\n    const l = Math.max(gain(n.left), 0), r = Math.max(gain(n.right), 0);\n    best = Math.max(best, n.val + l + r);\n    return n.val + Math.max(l, r);\n  };\n  gain(root);\n  return best;\n}',
