        approach="Monotonic decreasing deque of indices; the front is always the window maximum.",
        py='from collections import deque\ndef max_sliding_window(nums, k):\n    dq, res = deque(), []\n    for i, x in enumerate(nums):\n        while dq and nums[dq[-1]] <= x:\n            dq.pop()\n        dq.append(i)\n        if dq[0] <= i - k:\n            dq.popleft()\n        if i >= k - 1:\n            res.append(nums[dq[0]])\n    return res',
