        py='import heapq\ndef merge_k_lists(lists):\n    h = [(l.val, i, l) for i, l in enumerate(lists) if l]\n    heapq.heapify(h)\n    dummy = cur = ListNode(0)\n    while h:\n        _, i, n = heapq.heappop(h)\n        cur.next = n\n        cur = n\n        if n.next:\n            heapq.heappush(h, (n.next.val, i, n.next))\n    return dummy.next',
        js='function mergeKLists(lists) {\n  const merge = (a, b) => {\n    const d = { next: null };\n    let c = d;\n    while (a && b) {\n      if (a.val <= b.val) { c.next = a; a = a.next; }\n      else { c.next = b; b = b.next; }\n      c = c.next;\n    }\n    c.next = a || b;\n    return d.next;\n  };\n  if (!lists.length) return null;\n  while (lists.length > 1) {\n    const nx = [];\n    for (let i = 0; i < lists.length; i += 2)\n      nx.push(i + 1 < lists.length ? merge(lists[i], lists[i + 1]) : lists[i]);\n    lists = nx;\n  }\n  return lists[0];\n}',
