        id="min-window-substr",
        title="Minimum Window Substring",
        problem="Smallest substring of s containing every character of t (with multiplicity).",
        example='"ADOBECODEBANC","ABC" → "BANC"',
        approach="Sliding window with a need-count map and a 'missing' counter; shrink from the left once the window is valid.",
        py='from collections import Counter\ndef min_window(s, t):\n    need, missing = Counter(t), len(t)\n    best, l = "", 0\n    for r, ch in enumerate(s):\n        if need[ch] > 0:\n            missing -= 1\n        need[ch] -= 1\n        if missing == 0:\n            while need[s[l]] < 0:\n                need[s[l]] += 1\n                l += 1\n            if not best or r - l + 1 < len(best):\n                best = s[l:r + 1]\n            need[s[l]] += 1\n            missing += 1\n            l += 1\n    return best',
        js='function minWindow(s, t) {\n  const need = {};\n  for (const ch of t) need[ch] = (need[ch] || 0) + 1;\n  let missing = t.length, best = "", l = 0;\n  for (let r = 0; r < s.length; r++) {\n    const ch = s[r];\n    if ((need[ch] || 0) > 0) missing--;\n    need[ch] = (need[ch] || 0) - 1;\n    if (missing === 0) {\n      while (need[s[l]] < 0) { need[s[l]]++; l++; }\n      if (!best || r - l + 1 < best.length) best = s.slice(l, r + 1);\n      need[s[l]]++;\n      missing++;\n      l++;\n    }\n  }\n  return best;\n}',
