        approach="Backtracking: try each prefix that is a palindrome, then recurse on the rest.",
        py='def partition(s):\n    res = []\n    def bt(i, path):\n        if i == len(s):\n            res.append(path[:])\n            return\n        for j in range(i + 1, len(s) + 1):\n            p = s[i:j]\n            if p == p[::-1]:\n                path.append(p)\n                bt(j, path)\n                path.pop()\n    bt(0, [])\n    return res',
        js='function partition(s) {\n  const res = [];\n  const isPal = p => p === [...p].reverse().join("");\n  const bt = (i, path) => {\n    if (i === s.length) { res.push([...path]); return; }\n    for (let j = i + 1; j <= s.length; j++) {\n      const p = s.slice(i, j);\n      if (isPal(p)) { path.push(p); bt(j, path); path.pop(); }\n    }\n  };\n  bt(0, []);\n  return res;\n}',
        time="O(n·2ⁿ)",
        space="O(n)",
        pattern="Backtracking",
