        title="Network Delay Time",
        problem="Time for a signal from node k to reach all n nodes, or -1.",
        example="times=[[2,1,1],[2,3,1],[3,4,1]], n=4, k=2 → 2",
        approach="Bellman-Ford: relax every edge up to n−1 times; answer is the largest distance.",
        py='def network_delay_time(times, n, k):\n    INF = float("inf")\n    dist = [INF] * (n + 1)\n    dist[k] = 0\n    for _ in range(n - 1):\n        for u, v, w in times:\n            if dist[u] + w < dist[v]:\n                dist[v] = dist[u] + w\n    m = max(dist[1:])\n    return m if m < INF else -1',
        js='function networkDelayTime(times, n, k) {\n  const dist = Array(n + 1).fill(Infinity);\n  dist[k] = 0;\n  for (let i = 0; i < n - 1; i++)\n    for (const [u, v, w] of times)\n      if (dist[u] + w < dist[v]) dist[v] = dist[u] + w;\n  const m = Math.max(...dist.slice(1));\n  return m === Infinity ? -1 : m;\n}',
