        approach="Per key keep time-ordered entries (timestamps increase); binary-search for the rightmost ts ≤ query.",
        py='from bisect import bisect_right\nfrom collections import defaultdict\nclass TimeMap:\n    def __init__(self):\n        self.d = defaultdict(lambda: ([], []))\n    def set(self, k, v, t):\n        ts, vs = self.d[k]\n        ts.append(t)\n        vs.append(v)\n    def get(self, k, t):\n        if k not in self.d:\n            return ""\n        ts, vs = self.d[k]\n        i = bisect_right(ts, t)\n        return vs[i - 1] if i else ""',
        js='class TimeMap {\n  constructor() { this.d = new Map(); }\n  set(k, v, t) {\n    if (!this.d.has(k)) this.d.set(k, []);\n    this.d.get(k).push([t, v]);\n  }\n  get(k, t) {\n    const a = this.d.get(k) || [];\n    let lo = 0, hi = a.length;\n    while (lo < hi) {\n      const m = (lo + hi) >> 1;\n      if (a[m][0] <= t) lo = m + 1;\n      else hi = m;\n    }\n    return lo ? a[lo - 1][1] : "";\n  }\n}',
